-- Run once in Supabase SQL Editor. Disable public signup in Auth settings.
create extension if not exists pgcrypto;
create table public.projects(id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,name text not null,description text not null default '',goal text not null default '',stack text not null default '',constraints text not null default '',acceptance text not null default '',repo_url text not null default '',version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.tasks(id uuid primary key,project_id uuid not null references public.projects(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,title text not null,description text not null default '',acceptance text not null default '',status text not null default 'جديدة',priority text not null default 'متوسطة',mode text not null default 'lead',lead_tool text not null default 'chatgpt',round_limit integer not null default 3 check(round_limit between 1 and 20),final_result text not null default '',verification text not null default 'مقترح',version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.rounds(id uuid primary key,task_id uuid not null references public.tasks(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,tool text not null,role text not null,prompt text not null,response text not null default '',version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.attachments(id uuid primary key,project_id uuid not null references public.projects(id) on delete cascade,task_id uuid references public.tasks(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,name text not null,mime text not null,size bigint not null check(size between 0 and 10485760),storage_path text not null unique,created_at timestamptz not null default now());
create table public.memories(id uuid primary key,owner_id uuid not null references auth.users(id) on delete cascade,project_id uuid references public.projects(id) on delete cascade,task_id uuid references public.tasks(id) on delete cascade,content text not null,source text not null default 'إدخال مباشر',inferred boolean not null default false,version integer not null default 1,created_at timestamptz not null default now());
-- Single-owner deployment: set the actual Auth user UUID before executing this migration.
-- Replace placeholder below with the UUID from Authentication > Users.
create or replace function public.is_app_owner() returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() = '00000000-0000-0000-0000-000000000000'::uuid $$;
revoke all on function public.is_app_owner() from public;grant execute on function public.is_app_owner() to authenticated;
-- Restrict all rows to the designated owner; additionally prevent forged cross-parent relationships.
do $$ declare t text; begin foreach t in array array['projects','tasks','rounds','attachments','memories'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy owner_only on public.%I for all to authenticated using (public.is_app_owner() and owner_id=auth.uid()) with check (public.is_app_owner() and owner_id=auth.uid())',t);end loop;end $$;
create or replace function public.validate_parent_owner() returns trigger language plpgsql security definer set search_path='' as $$ begin if tg_table_name='tasks' and not exists(select 1 from public.projects p where p.id=new.project_id and p.owner_id=new.owner_id) then raise exception 'invalid project';end if;if tg_table_name='rounds' and not exists(select 1 from public.tasks t where t.id=new.task_id and t.owner_id=new.owner_id) then raise exception 'invalid task';end if;if tg_table_name='attachments' and (not exists(select 1 from public.projects p where p.id=new.project_id and p.owner_id=new.owner_id) or (new.task_id is not null and not exists(select 1 from public.tasks t where t.id=new.task_id and t.project_id=new.project_id and t.owner_id=new.owner_id))) then raise exception 'invalid attachment parent';end if;if tg_table_name='memories' and ((new.project_id is not null and not exists(select 1 from public.projects p where p.id=new.project_id and p.owner_id=new.owner_id)) or (new.task_id is not null and not exists(select 1 from public.tasks t where t.id=new.task_id and t.owner_id=new.owner_id and (new.project_id is null or t.project_id=new.project_id)))) then raise exception 'invalid memory parent';end if;return new;end $$;
do $$ declare t text; begin foreach t in array array['tasks','rounds','attachments','memories'] loop execute format('create trigger validate_parent before insert or update on public.%I for each row execute function public.validate_parent_owner()',t);end loop;end $$;
insert into storage.buckets(id,name,public,file_size_limit) values('private-files','private-files',false,10485760) on conflict(id) do nothing;
create policy private_read on storage.objects for select to authenticated using(bucket_id='private-files' and public.is_app_owner() and (storage.foldername(name))[1]=auth.uid()::text);
create policy private_insert on storage.objects for insert to authenticated with check(bucket_id='private-files' and public.is_app_owner() and (storage.foldername(name))[1]=auth.uid()::text);
create policy private_delete on storage.objects for delete to authenticated using(bucket_id='private-files' and public.is_app_owner() and (storage.foldername(name))[1]=auth.uid()::text);
